from decimal import Decimal, ROUND_HALF_UP

CENTS = Decimal('0.01')


def _to_cents(value):
    return value.quantize(CENTS, rounding=ROUND_HALF_UP)


def invoice(lines, tax_rate):
    tax_rate = Decimal(tax_rate)

    rounded_lines = []
    for row in lines:
        extended = Decimal(row['unit_price']) * row['qty']
        rounded_lines.append((row['taxable'], _to_cents(extended)))

    subtotal = sum((rounded for _, rounded in rounded_lines), Decimal('0'))
    tax = sum((_to_cents(rounded * tax_rate) for taxable, rounded in rounded_lines if taxable), Decimal('0'))
    total = subtotal + tax

    def _fmt(value):
        if value == 0:
            value = Decimal('0')
        return f'{value:.2f}'

    return {'subtotal': _fmt(subtotal), 'tax': _fmt(tax), 'total': _fmt(total)}
